namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;

    public int RatingCount => Ratings.Count;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes over dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy pasta with pancetta, egg, and Parmesan.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated Parmesan and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta, then stir in egg mixture off heat.", "Serve immediately with extra Parmesan."],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce, cream, and spices; simmer.", "Add chicken to sauce and cook 10 minutes.", "Serve over basmati rice."],
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Samosas", Category = "Indian",
                Description = "Crispy pastry filled with spiced potatoes and peas.",
                Ingredients = ["Potatoes", "Peas", "Cumin seeds", "Garam masala", "Flour", "Oil for frying", "Green chilies", "Cilantro"],
                Steps = ["Boil and mash potatoes.", "Cook peas with cumin, garam masala, and chilies.", "Mix potatoes and peas together.", "Prepare dough from flour, water, and oil.", "Shape into cones, fill with potato mixture, and seal.", "Deep fry until golden brown."],
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
                Steps = ["Brown ground beef with diced onion.", "Add taco seasoning and water; simmer.", "Warm taco shells in oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, and sour cream.", "Serve with salsa and lime wedges."],
                Ratings = [4, 5, 4, 4]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt", "Garlic"],
                Steps = ["Halve and pit avocados; scoop into bowl.", "Mash to desired consistency.", "Stir in lime juice, diced onion, jalapeño, and tomato.", "Add chopped cilantro and minced garlic.", "Season with salt to taste.", "Serve immediately with tortilla chips."],
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Ramen", Category = "Japanese",
                Description = "Rich miso broth with noodles, pork, and soft-boiled egg.",
                Ingredients = ["Ramen noodles", "Miso paste", "Pork belly", "Soft-boiled eggs", "Green onions", "Nori", "Sesame oil", "Chicken broth", "Soy sauce", "Garlic"],
                Steps = ["Simmer chicken broth with garlic and ginger.", "Whisk in miso paste and soy sauce.", "Cook ramen noodles according to package.", "Sear sliced pork belly until caramelized.", "Assemble bowls: noodles, broth, pork, halved egg.", "Garnish with green onions, nori, and sesame oil."],
                Ratings = [5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Warm chocolate cake with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F and grease ramekins.", "Melt chocolate and butter together.", "Whisk in eggs, sugar, and vanilla.", "Fold in flour until just combined.", "Pour into ramekins and bake 12-14 minutes.", "Invert onto plates and serve immediately."],
                Ratings = [5, 5, 5, 5, 4]
            }
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

