@using RecipeShare.Services

<div class="my-3">
    <span class="me-2"><strong>Rate this recipe:</strong></span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span role="button"
              style="font-size: 1.5rem; cursor: pointer; color: @(star <= (_hoverStar ?? _selectedStar) ? "#ffc107" : "#dee2e6")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => _hoverStar = star"
              @onmouseout="() => _hoverStar = null">★</span>
    }

    @if (_submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }

    <small class="text-muted ms-2">
        @if (RatingCount > 0)
        {
            @($"Average: {CurrentRating} / 5 ({RatingCount} ratings)")
        }
        else
        {
            @("No ratings yet — be the first!")
        }
    </small>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int _selectedStar;
    private int? _hoverStar;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _selectedStar = stars;
        _submitted = true;

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>📤 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe submitted!</h4>
        <p>Your recipe "<strong>@_model.Title</strong>" has been added to the <strong>@_model.Category</strong> category.</p>
        <a href="category/@_model.Category" class="btn btn-primary me-2">View Category</a>
        <button class="btn btn-outline-secondary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label">Recipe Title</label>
            <InputText class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label class="form-label">Description</label>
            <InputTextArea class="form-control" @bind-Value="_model.Description" rows="2"
                           placeholder="A short description of your recipe" />
            <ValidationMessage For="() => _model.Description" />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients (one per line)</label>
            <InputTextArea class="form-control" @bind-Value="_ingredientsText" rows="5"
                           placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps (one per line)</label>
            <InputTextArea class="form-control" @bind-Value="_stepsText" rows="5"
                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
